"<!doctype html>\n"
"<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>AAI10 \u00b7 Car testing</title>\n"
"<style>\n"
":root{font:16px system-ui,sans-serif;color:#e8eef7;background:#0e1622;color-scheme:dark}*{box-sizing:border-box}body{max-width:780px;margin:auto;padding:24px}h1{font-size:1.8rem;margin:0}h2{font-size:1rem;margin:0 0 10px}p{line-height:1.5;color:#b9c8da;margin:10px 0}.top,.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.top{justify-content:space-between;margin-bottom:20px}.version,small{color:#a9b9cc;font-size:.85rem}.card{background:#182536;border:1px solid #304057;border-radius:14px;padding:20px;margin-bottom:16px}button,select,input{font:inherit;border:1px solid #4a627e;border-radius:8px;padding:11px 14px;color:#fff;background:#243a50}button{cursor:pointer}button:hover{background:#355570}button:disabled,select:disabled,input:disabled{opacity:.45;cursor:default}.primary{background:#167766;flex:1}.stop{background:#a52d40}label{display:block;color:#b9c8da;margin:0 0 7px}select{width:100%;background:#101b2a}input{max-width:100%}.field{flex:1;min-width:220px}#connection{font-size:.85rem;color:#ffd18a}#connection.online{color:#80e6ca}.actions{margin-top:18px}#message{min-height:1.5em;color:#91eadb}details{margin-top:16px}summary{cursor:pointer;color:#b9c8da;padding:6px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.4;font-size:12px;background:#0b1420;padding:12px;border-radius:8px;max-height:300px;overflow:auto}canvas{display:block;width:100%;height:180px;background:#0b1420;border-radius:8px;margin-top:12px}[hidden]{display:none!important}.footer{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}#download{background:#243a50}#route-advance{width:130px}@media(max-width:500px){body{padding:14px}.card{padding:16px}.actions button{min-height:48px}.field{min-width:100%}}\n"
"</style></head><body>\n"
"<header class=\"top\"><div><h1>Car testing</h1><span class=\"version\">AAI10 \u00b7 v5.34</span></div><span id=\"connection\" role=\"status\">Connecting\u2026</span></header>\n"
"<main>\n"
"<section class=\"card\">\n"
"<label for=\"test-mode\">Test</label>\n"
"<select id=\"test-mode\" class=\"setting\" disabled>\n"
"<option value=\"v\">Barcode sensor check \u00b7 motors off</option>\n"
"<option value=\"course\">Follow track + read barcodes</option>\n"
"<option value=\"f\">30 cm forward</option><option value=\"l\">Left 90\u00b0</option><option value=\"r\">Right 90\u00b0</option><option value=\"u\">Right 180\u00b0</option>\n"
"</select>\n"
"<p id=\"test-help\">Keep the car still. Start on white, then slide the whole barcode underneath once during the five-second recording, finishing on white.</p>\n"
"<div id=\"course-options\" hidden><details id=\"barcode-actions\"><summary>Y/Z actions \u00b7 default: keep following</summary><p>A and other letters are recorded only. These are your test instructions.</p><div class=\"row\">\n"
"<div class=\"field\"><label for=\"y-action\">When Y is read</label><select id=\"y-action\" class=\"setting\"><option value=\"s\">Go straight \u2014 cancel pending turn</option><option value=\"L\">Turn left 90\u00b0 now</option><option value=\"R\">Turn right 90\u00b0 now</option><option value=\"U\">U-turn 180\u00b0 now</option><option value=\"l\">Turn left at next junction</option><option value=\"r\">Turn right at next junction</option><option value=\"a\">Skip 1 junction, then turn left</option><option value=\"b\">Skip 1 junction, then turn right</option><option value=\"c\">Skip 2 junctions, then turn left</option><option value=\"d\">Skip 2 junctions, then turn right</option><option value=\"x\">Stop now</option></select></div>\n"
"<div class=\"field\"><label for=\"z-action\">When Z is read</label><select id=\"z-action\" class=\"setting\"><option value=\"s\">Go straight \u2014 cancel pending turn</option><option value=\"L\">Turn left 90\u00b0 now</option><option value=\"R\">Turn right 90\u00b0 now</option><option value=\"U\">U-turn 180\u00b0 now</option><option value=\"l\">Turn left at next junction</option><option value=\"r\">Turn right at next junction</option><option value=\"a\">Skip 1 junction, then turn left</option><option value=\"b\">Skip 1 junction, then turn right</option><option value=\"c\">Skip 2 junctions, then turn left</option><option value=\"d\">Skip 2 junctions, then turn right</option><option value=\"x\">Stop now</option></select></div>\n"
"</div><p><small>A new Y/Z replaces a waiting turn. A turn already underway finishes first; Stop overrides. Barcode reading continues during turns and line recovery.</small></p>\n"
"<label for=\"route-advance\">Advance before a junction turn (mm)</label><input id=\"route-advance\" class=\"setting\" type=\"number\" min=\"60\" max=\"250\" step=\"1\" value=\"120\">\n"
"</details></div>\n"
"<div class=\"row actions\"><button id=\"prepare\" class=\"primary\" disabled>Record sensor \u00b7 5 seconds</button><button id=\"stop\" class=\"stop\">Stop</button></div>\n"
"<p id=\"message\" role=\"status\">Waiting for the car.</p>\n"
"<small id=\"start-help\">No GP20 start needed. GP20 cancels this sensor test.</small>\n"
"</section>\n"
"<section id=\"optical-panel\" class=\"card\"><h2>Sensor result</h2><p id=\"optical-summary\" role=\"status\">No recording yet.</p><canvas id=\"optical-plot\" width=\"900\" height=\"220\" aria-label=\"Barcode sensor readings across five seconds\" hidden></canvas><small id=\"plot-help\" hidden>Higher readings mean darker. Dashed lines: 226 / 220. Driving uses a 10 ms average; this graph shows raw readings and does not confirm a decoded barcode.</small></section>\n"
"<div class=\"footer\"><button id=\"download\">Download log</button><small>One file includes every test. Save before switching off.</small></div>\n"
"<details id=\"technical\"><summary>Live log &amp; technical details</summary><h2>Latest saved result</h2><pre id=\"result\">Results are retrieved automatically when a test finishes or you download.</pre><h2>Live log</h2><pre id=\"log\" aria-label=\"Robot diagnostic log\"></pre><p><small>IR order: barcode GP26 / line centre GP28 / line right GP27. Keep GP28 directly over the black tape. The car cannot detect table edges. Web Stop needs Wi-Fi; GP20 is the local stop. Captured logs remain in this page; power resets clear results on the car.</small></p></details>\n"
"</main>\n"
"<script>\n"
"'use strict';\n"
"let cursor=0, boot='', transcript='', busy=false, online=false, robotIdle=false, downloadedResult='', requestBusy=false;\n"
"const el=id=>document.getElementById(id);\n"
"function append(text){inspectOptical(text);transcript+=text;if(transcript.length>1048576)transcript='[BROWSER LOG TRIMMED: earlier text removed]\\n'+transcript.slice(-1000000);el('log').textContent=transcript.slice(-50000);el('log').scrollTop=el('log').scrollHeight;}\n"
"let opticalLines='',opticalBins=[];\n"
"function updateMode(){const mode=el('test-mode').value;el('course-options').hidden=mode!=='course';el('optical-panel').hidden=mode!=='v';el('prepare').textContent=mode==='v'?'Record sensor \u00b7 5 seconds':'Prepare run';el('test-help').textContent=mode==='v'?'Keep the car still. Start on white, then slide the whole barcode underneath once during the five-second recording, finishing on white.':mode==='course'?'Centre GP28 over the tape; keep GP27 beside it. Default: follow the track, go straight through crossings and record barcodes.':'Place the car on a clear, flat surface for the selected movement.';el('start-help').textContent=mode==='v'?'No GP20 start needed. GP20 cancels this sensor test.':'After confirmation, press GP20 on the car. Hold it still through the 3-second countdown. GP20 also stops it.';}\n"
"el('test-mode').onchange=()=>{updateMode();drawOptical();};\n"
"window.addEventListener('resize',drawOptical);\n"
"function drawOptical(){\n"
" const canvas=el('optical-plot');if(!canvas.clientWidth)return;const w=canvas.clientWidth,h=180,ratio=window.devicePixelRatio||1;canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);\n"
" ctx.clearRect(0,0,w,h);ctx.fillStyle='#0b1420';ctx.fillRect(0,0,w,h);\n"
" const top=Math.max(300,...opticalBins.filter(Boolean).map(v=>v[1]))*1.1;\n"
" const y=v=>h-25-v/top*(h-40),x=i=>48+i/500*(w-60);\n"
" ctx.font='13px system-ui';ctx.fillStyle='#b9c8da';ctx.fillText('Raw '+Math.ceil(top),5,15);ctx.fillText('0 s',48,h-5);ctx.fillText('5 s',w-30,h-5);\n"
" ctx.strokeStyle='#ffbd69';ctx.setLineDash([5,4]);\n"
" for(const value of [220,226]){ctx.beginPath();ctx.moveTo(48,y(value));ctx.lineTo(w-10,y(value));ctx.stroke();ctx.fillText(String(value),value===220?5:w-35,y(value)-3);}\n"
" ctx.setLineDash([]);ctx.strokeStyle='#70dbca';\n"
" opticalBins.forEach((v,i)=>{if(!v)return;ctx.beginPath();ctx.moveTo(x(i),y(v[0]));ctx.lineTo(x(i),y(v[1])-1);ctx.stroke();});\n"
"}\n"
"function inspectOptical(text){\n"
" opticalLines+=text;const lines=opticalLines.split('\\n');opticalLines=lines.pop();\n"
" for(const line of lines){\n"
"  if(line.startsWith('[SELECT'))el('message').textContent=/Rejected|Use course|disabled/.test(line)?'Selection rejected. Stop the car and try again.':'Ready. Press GP20 on the car to start.';\n"
"  if(line.startsWith('[START]'))el('message').textContent='Starting \u00b7 keep the car still through the countdown.';\n"
"  if(line.startsWith('[MOTION GO]'))el('message').textContent='Running \u00b7 GP20 or Stop ends the run.';\n"
"  if(line.startsWith('[STOP]')||line.startsWith('[MOTION STOP]'))el('message').textContent='Stopped. Wait for the settled result, then download the log.';\n"
"  if(line.startsWith('[OPTICAL START]')&&line.includes('source=DRIVE')){opticalBins=[];el('message').textContent='Run finished. Download log includes the driving sensor recording.';continue;}\n"
"  if(line.startsWith('[OPTICAL START]')){opticalBins=[];el('optical-plot').hidden=false;el('plot-help').hidden=false;el('message').textContent='Recording now \u00b7 slide the barcode underneath. Motors stay off.';el('optical-summary').textContent='Recording for five seconds \u00b7 motors off \u00b7 slide paper now.';drawOptical();}\n"
"  if(line.startsWith('[OPTICAL RESULT]')){\n"
"   const samples=line.match(/samples=(\\d+)/),range=line.match(/raw=(\\d+)\\.\\.(\\d+)/),gap=line.match(/max_gap_us=(\\d+)/);\n"
"   const ok=line.includes('sampling_ok=1'),aborted=line.includes('aborted=1');\n"
"   el('optical-summary').textContent=(aborted?'Cancelled. ':ok?'Recording complete. ':'Recording incomplete. ')+(samples?samples[1]+' samples. ':'')+(range?'Readings '+range[1]+'\u2013'+range[2]+'. ':'')+(gap?'Largest sampling gap '+(Number(gap[1])/1000).toFixed(2)+' ms.':'');\n"
"  }\n"
"  if(line.startsWith('[OPTICAL END]'))el('message').textContent='Recording saved. Download log to share it.';\n"
"  const m=line.match(/^\\[OPTICAL DATA\\] bin=(\\d+) (.*)$/);\n"
"  if(m){let i=Number(m[1]);for(const item of m[2].split(' ')){if(i<500)opticalBins[i]=/^\\d+:\\d+$/.test(item)?item.split(':').map(Number):null;i++;}drawOptical();}\n"
" }\n"
" if(opticalLines.length>4096)opticalLines='';\n"
"}\n"
"function setOnline(value){online=value;el('connection').textContent=value?'Connected':'Offline \u00b7 join AAI10-Calibrate';el('connection').className=value?'online':'offline';refreshButtons();}\n"
"function refreshButtons(){document.querySelectorAll('.setting,#prepare').forEach(b=>b.disabled=!online||!robotIdle||requestBusy);}\n"
"async function request(path,options={}){const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),3500);try{return await fetch(path,{...options,cache:'no-store',signal:ctl.signal});}finally{clearTimeout(timer);}}\n"
"async function poll(){if(busy)return;busy=true;try{const r=await request('/logs?since='+cursor);if(!r.ok)throw Error('HTTP '+r.status);const newBoot=r.headers.get('X-Boot');const next=Number(r.headers.get('X-Next'));let text=await r.text();if(boot&&newBoot!==boot){append('\\n[CAR POWER RESET: previous selection and retained results cleared]\\n');cursor=0;downloadedResult='';opticalBins=[];drawOptical();el('optical-summary').textContent='Car restarted; capture cleared.';robotIdle=false;refreshButtons();el('message').textContent='Car restarted. Choose a test and prepare it again.';el('optical-plot').hidden=true;el('plot-help').hidden=true;el('result').textContent='Car restarted; no current result.';boot=newBoot;return;}boot=newBoot;if(r.headers.get('X-Gap')==='1')append('\\n[LOG GAP: older car log bytes unavailable; download includes the retained result]\\n');cursor=next;const wasIdle=robotIdle,wasOnline=online;robotIdle=r.headers.get('X-Idle')==='1';setOnline(true);append(text);if(robotIdle&&(!wasIdle||!wasOnline))recover();}catch(e){setOnline(false);}finally{busy=false;setTimeout(poll,500);}}\n"
"async function sendSelection(path){requestBusy=true;refreshButtons();try{const r=await request(path,{method:'POST',headers:{'X-Calibrate':'1'}});const reply=await r.text();if(!r.ok)throw Error(reply);el('message').textContent=path==='/command/v'?'Requested. Wait for the recording confirmation.':path==='/command/x'?'Stop requested. GP20 stops locally if Wi-Fi is unavailable.':'Requested. Wait for the ready confirmation before pressing GP20.';append('\\n[BROWSER] '+reply+'\\n');}catch(e){el('message').textContent='Request not confirmed. Check the live log; use GP20 to abort locally.';}finally{requestBusy=false;refreshButtons();}}\n"
"function command(ch){return sendSelection('/command/'+ch);}\n"
"el('prepare').onclick=()=>{\n"
" const mode=el('test-mode').value;\n"
" if(mode!=='course'){command(mode);return;}\n"
" const advance=Number(el('route-advance').value),y=el('y-action').value,z=el('z-action').value;\n"
" if(!Number.isInteger(advance)||advance<60||advance>250){el('message').textContent='Use junction advance 60\u2013250 mm.';el('barcode-actions').open=true;return;}\n"
" sendSelection('/mission/'+y+'/'+z+'/'+advance);\n"
"};\n"
"el('stop').onclick=()=>command('x');\n"
"async function recover(){try{const r=await request('/result');if(!r.ok)throw Error();downloadedResult=await r.text();el('result').textContent=downloadedResult;}catch(e){downloadedResult='Could not retrieve the current car result; use captured live log below.\\n';el('result').textContent='Could not reach the car. Reconnect and try again.';}}\n"
"el('download').onclick=async()=>{await recover();const metadata='AAI10 v5.34 wireless calibration\\nSaved: '+new Date().toISOString()+'\\nCar boot: '+boot+'\\nPhysical observations supplied separately in chat.\\n\\n';const blob=new Blob([metadata,'RECOVERED RESULT (may duplicate log):\\n',downloadedResult,'\\nLIVE LOG:\\n',transcript],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='AAI10-motion-'+new Date().toISOString().replace(/[:.]/g,'-')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\n"
"updateMode();\n"
"poll();\n"
"</script></body></html>\n";
#endif
